Use a count to distinguish empty from full: count is always between 0 and 17, head identifies the next item to pop, and tail equals (head + count) modulo 17. Head and tail coincide both when empty and when full; count distinguishes those states, and rejected operations leave the queue unchanged. Compile with C++17 and assertions enabled, for example: g++ -std=c++17 fifo.cpp -o fifo, then run the executable.

```cpp
#include <array>
#include <cassert>
#include <cstddef>
#include <iostream>

class BoundedFIFO {
public:
    static constexpr std::size_t capacity = 17;

    bool push(int value) {
        if (count_ == capacity) return false;
        data_[tail_] = value;
        tail_ = (tail_ + 1) % capacity;
        ++count_;
        return true;
    }

    bool pop(int& value) {
        if (count_ == 0) return false;
        value = data_[head_];
        head_ = (head_ + 1) % capacity;
        --count_;
        return true;
    }

    std::size_t size() const { return count_; }

private:
    std::array<int, capacity> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t count_ = 0;
};

int main() {
    BoundedFIFO queue;
    int value = -1;

    assert(!queue.pop(value));
    assert(value == -1);
    assert(queue.size() == 0);

    for (int i = 0; i < 17; ++i) {
        assert(queue.push(i));
        assert(queue.size() == static_cast<std::size_t>(i + 1));
    }

    assert(!queue.push(999));
    assert(queue.size() == 17);

    // This verifies that rejection preserved every queued item.
    for (int i = 0; i < 17; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    assert(queue.size() == 0);
    assert(!queue.pop(value));

    // Keep seven items while wrapping the insertion index.
    for (int i = 0; i < 17; ++i) assert(queue.push(i));
    for (int i = 0; i < 10; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    for (int i = 17; i < 27; ++i) assert(queue.push(i));
    assert(queue.size() == 17);
    assert(!queue.push(999));

    // Drain across the physical array boundary in FIFO order.
    for (int i = 10; i < 27; ++i) {
        assert(queue.pop(value));
        assert(value == i);
    }
    assert(queue.size() == 0);
    assert(!queue.pop(value));

    std::cout << "All tests passed\n";
}
```

The lower median is 4: sorted, the values are [1,2,4,4,7,9]. Copy the input before using std::nth_element, so the caller’s array stays unchanged; reject empty input with std::invalid_argument.

The correct zero-based index is (n - 1) / 2 using integer division. For odd n = 2k + 1, this gives k, the middle element. For even n = 2k, it gives k - 1, the lower of the two middle elements. std::nth_element places the same value at that index as a full sort would, including when values repeat.

Compile with C++17 and assertions enabled: g++ -std=c++17 median.cpp -o median, then run ./median.

```cpp
#include <algorithm>
#include <cassert>
#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <vector>

int lower_median(const std::vector<int>& input) {
    if (input.empty()) {
        throw std::invalid_argument("lower_median requires nonempty input");
    }

    std::vector<int> copy = input;
    const std::size_t index = (copy.size() - 1) / 2;
    auto selected = copy.begin() +
        static_cast<std::vector<int>::difference_type>(index);
    std::nth_element(copy.begin(), selected, copy.end());
    return *selected;
}

int main() {
    const auto check = [](const std::vector<int>& input, int expected) {
        const std::vector<int> original = input;
        const int actual = lower_median(input);
        assert(actual == expected);
        assert(input == original);
    };

    check({9, 1, 4, 4, 7, 2}, 4); // Requested array; duplicates.
    check({5, 5, 5, 5}, 5);       // All values identical.
    check({9, 1, 7, 3, 5}, 5);    // Odd size.
    check({8, 2, 6, 4}, 4);       // Even size; lower middle.
    check({42}, 42);              // Singleton.

    const std::vector<int> empty;
    bool rejected = false;
    try {
        (void)lower_median(empty);
    } catch (const std::invalid_argument&) {
        rejected = true;
    }
    assert(rejected);
    assert(empty.empty());

    std::cout << "All tests passed\n";
    return 0;
}
```

No. A successful retry can store a stale desired value and lose an increment.

Starting at 0, threads A and B both set expected=0 and desired=1. A successfully changes 0 to 1. B’s comparison fails, updating its expected to 1 but leaving desired=1; its retry successfully changes 1 to 1. Both calls finish, but the count is 1 rather than 2.

Recompute desired from expected before every attempt. A spurious failure also retries: whether expected changes or stays the same, the next attempt proposes expected+1. This implementation uses relaxed ordering because it only maintains a counter, not synchronization for other data; the tested totals cannot overflow.

Compile with g++ -std=c++17 -O2 -pthread counter.cpp -o counter, without -DNDEBUG, then run ./counter.

```cpp
#include <atomic>
#include <cassert>
#include <cstdint>
#include <iostream>
#include <thread>
#include <vector>

void increment(std::atomic<std::uint64_t>& counter) {
    std::uint64_t expected = counter.load(std::memory_order_relaxed);
    for (;;) {
        const std::uint64_t desired = expected + 1;
        if (counter.compare_exchange_weak(
                expected, desired,
                std::memory_order_relaxed,
                std::memory_order_relaxed)) {
            return;
        }
        // Failure, including spurious failure, updates expected.
        // Recompute desired at the beginning of the next iteration.
    }
}

int main() {
    constexpr unsigned thread_count = 8;
    constexpr std::uint64_t increments_per_thread = 100000;
    constexpr std::uint64_t expected_total =
        thread_count * increments_per_thread;

    std::atomic<std::uint64_t> counter{0};
    std::atomic<bool> start{false};
    std::vector<std::thread> workers;
    workers.reserve(thread_count);

    for (unsigned t = 0; t < thread_count; ++t) {
        workers.emplace_back([&] {
            while (!start.load(std::memory_order_acquire)) {
                std::this_thread::yield();
            }
            for (std::uint64_t i = 0; i < increments_per_thread; ++i) {
                increment(counter);
            }
        });
    }

    start.store(true, std::memory_order_release);
    for (auto& worker : workers) {
        worker.join();
    }

    const auto actual = counter.load(std::memory_order_relaxed);
    assert(actual == expected_total);
    std::cout << "All tests passed: " << actual << '\n';
    return 0;
}
```
